        <div class="seg" role="group" aria-label="العرض">${[['draft', 'عندي (المسودة)'], ['pub', 'المنشور للطلاب'], ['cmp', 'مقارنة']].map(([k, l]) => `<button data-mode="${k}" aria-pressed="${tts.mode === k}">${l}</button>`).join('')}</div>
