function teacherHistoryModal(teacherId) {
  const t = db.teacher(teacherId);
  if (!t) return;
  const ds = db.days();
  modal(`سجل دوام وبصمات: ${t.name}`, `<div style="display:flex;flex-direction:column;gap:12px">
    <div style="display:flex;justify-content:space-between;align-items:center;background:var(--surface-200);padding:10px 14px;border-radius:10px">
      <div><b>${esc(t.name)}</b> <span class="muted">(${esc(t.subject || 'عام')})</span></div>
      <div class="muted small num" dir="ltr">${esc(t.phone)}</div>
    </div>
    <div class="tablewrap" style="max-height:55vh;overflow:auto">
      <table>
        <thead>
          <tr>
            <th>اليوم والتاريخ</th>
            <th>بصمة الدخول</th>
            <th>بصمة الانصراف</th>
            <th>الحالة</th>
          </tr>
        </thead>
        <tbody>
          ${ds.map(d => {
    const st = db.teacherStatusOf(t.id, d);
    const inTime = st.inEv ? fmtTime(st.inEv.ts) : '—';
    const inDev = st.inEv ? (st.inEv.deviceId ? db.device(st.inEv.deviceId)?.name.split(' · ')[0] : 'يدوي') : '';
    const outTime = st.outEv ? fmtTime(st.outEv.ts) : '—';
    let pillHtml = '';
    if (st.status === 'present') pillHtml = '<span class="pill p-present">حاضر ✓</span>';
    else if (st.status === 'late') pillHtml = '<span class="pill p-late">متأخر ⏱</span>';
    else if (st.status === 'left') pillHtml = '<span class="pill p-left">انصرف ⏏</span>';
    else if (st.status === 'excused') pillHtml = `<span class="pill p-excused">إجازة: ${esc(st.excuse?.reason || '')}</span>`;
    else if (st.status === 'holiday') pillHtml = '<span class="pill p-quiet">عطلة</span>';
    else if (st.status === 'pending') pillHtml = '<span class="pill p-quiet">لم يبصم</span>';
    else pillHtml = '<span class="pill p-absent">غائب</span>';

    return `<tr>
              <td><b>${fmtDay(new Date(d))}</b></td>
              <td>${inTime} ${inDev ? `<small class="muted">(${inDev})</small>` : ''}</td>
              <td>${outTime}</td>
              <td>${pillHtml}</td>
            </tr>`;
  }).join('')}
        </tbody>
      </table>
    </div>
    <div style="display:flex;justify-content:flex-end">
      <button class="btn" data-close>إغلاق</button>
    </div>
  </div>`);
}

async function staffReportPdf() {
  const st = db.settings();
  const rep = db.teacherMonthReport();
  const dt = new Date(db.now());
  const F = (w, z) => `${w} ${z}px Cairo, "Noto Naskh Arabic", "Segoe UI", Tahoma, sans-serif`;
  const W = 1240, M = 80;
  const NAVY = '#1E2B5C', TEAL = '#0B7F70', AMBER = '#F2A93B', RED = '#C8453F', MUTED = '#5B6478', LINE = '#E3E8EF';
  const pages = [];
  let pageNo = 0;

  const totalTeachers = rep.rows.length;
  const avgRate = totalTeachers ? Math.round(rep.rows.reduce((a, r) => a + r.rate, 0) / totalTeachers) : 100;
  const totLate = rep.rows.reduce((a, r) => a + r.c.late, 0);
  const totAbsent = rep.rows.reduce((a, r) => a + r.c.absent, 0);
  const totExc = rep.rows.reduce((a, r) => a + r.c.excused, 0);

  const header = (g, sub) => {
    pageNo++;
    g.fillStyle = NAVY;
    g.fillRect(0, 0, W, 170);
    g.fillStyle = '#fff';
    g.font = F(700, 44);
    g.fillText('تقرير دوام وحضور الكادر التعليمي', W - M, 90);
    g.font = F(400, 24);
    g.fillStyle = '#C9D6F0';
    g.fillText(`${st.schoolName} · السجل التراكمي لالتزام المدرسين${sub ? ' · ' + sub : ''}`, W - M, 138);
    g.textAlign = 'left';
    g.font = F(700, 36);
    g.fillStyle = '#fff';
    g.fillText('منصة حاضر', M, 100);
    g.textAlign = 'right';
    g.fillStyle = AMBER;
    g.fillRect(0, 170, W, 8);
  };

  const footer = g => {
    g.fillStyle = MUTED;
    g.font = F(400, 20);
    g.textAlign = 'center';
    g.fillText(`صفحة ${pageNo} · استخرج بتاريخ ${fmtDay(dt)} · نظام حاضر للبصمة البيومترية`, W / 2, 1715);
    g.textAlign = 'right';
  };

  const table = (g, y, cols, data, rowH = 50) => {
    let x = W - M;
    g.fillStyle = '#F5F7FA';
    g.fillRect(M, y, W - 2 * M, rowH);
    g.fillStyle = NAVY;
    g.font = F(700, 21);
    cols.forEach(([l, w]) => {
      g.fillText(l, x - 12, y + rowH * .64);
      x -= w;
    });
    y += rowH;
    g.font = F(400, 21);
    data.forEach((row, i) => {
      x = W - M;
      if (i % 2) {
        g.fillStyle = '#FBFCFD';
        g.fillRect(M, y, W - 2 * M, rowH);
      }
      row.forEach((v, j) => {
        g.fillStyle = typeof v === 'object' ? v.c : NAVY;
        g.fillText(String(typeof v === 'object' ? v.t : v), x - 12, y + rowH * .64);
        x -= cols[j][1];
      });
      g.strokeStyle = LINE;
      g.lineWidth = 1.2;
      g.beginPath();
      g.moveTo(M, y + rowH);
      g.lineTo(W - M, y + rowH);
      g.stroke();
      y += rowH;
    });
    return y;
  };

  const teacherData = rep.rows.map((r, idx) => [
    idx + 1,
    r.t.name,
    r.t.subject || 'عام',
    r.c.present,
    r.c.late,
    r.c.absent ? { t: r.c.absent, c: RED } : 0,
    r.c.excused,
    { t: r.rate + '%', c: r.rate >= 90 ? TEAL : r.rate >= 75 ? AMBER : RED }
  ]);

  const cols = [
    ['#', 60],
    ['اسم المدرس', 360],
    ['المادة', 160],
    ['حضور بالموعد', 130],
    ['تأخير', 110],
    ['غياب', 110],
    ['إجازة', 90],
    ['الالتزام', 90]
  ];

  const PER_FIRST = 20;
  const PER_SUB = 26;

  const firstChunk = teacherData.slice(0, PER_FIRST);
  pages.push(await pdfPage(g => {
    header(g, '');
    const cards = [
      ['الكادر الكلي', totalTeachers, NAVY],
      ['معدل الالتزام', avgRate + '%', TEAL],
      ['إجمالي التأخيرات', totLate, AMBER],
      ['إجمالي الغيابات', totAbsent, RED],
      ['إجازات رسمية', totExc, '#7A5BB0']
    ];
    const bw = (W - 2 * M - 4 * 16) / 5;
    cards.forEach(([l, v, col], i) => {
      const x = W - M - (i + 1) * bw - i * 16;
      g.fillStyle = '#F5F7FA';
      g.fillRect(x, 210, bw, 130);
      g.fillStyle = col;
      g.fillRect(x + bw - 8, 210, 8, 130);
      g.fillStyle = MUTED;
      g.font = F(600, 20);
      g.fillText(l, x + bw - 20, 250);
      g.fillStyle = col;
      g.font = F(700, 46);
      g.fillText(String(v), x + bw - 20, 314);
    });

    g.fillStyle = NAVY;
    g.font = F(700, 28);
    g.fillText(`سجل التزام المدرسين والمعلمين (${totalTeachers} مدرس)`, W - M, 390);

    table(g, 420, cols, firstChunk, 50);
    footer(g);
  }));

  for (let i = PER_FIRST; i < teacherData.length; i += PER_SUB) {
    const chunk = teacherData.slice(i, i + PER_SUB);
    pages.push(await pdfPage(g => {
      header(g, 'تابع سجل الكادر');
      table(g, 220, cols, chunk, 50);
      footer(g);
    }));
  }

  return {
    blob: jpegsToPdf(pages),
    name: `تقرير-دوام-الكادر-${dt.getFullYear()}-${dt.getMonth() + 1}.pdf`
  };
}

